import sys

data = sys.stdin.read().split()
m, n = int(data[0]), int(data[1])
g = data[2:2 + m]
best = 0
for i in range(m):
    for j in range(n):
        k = 1
        while i + k <= m and j + k <= n:
            if all(g[x][y] == '1' for x in range(i, i + k) for y in range(j, j + k)):
                best = max(best, k)
            k += 1
print(best * best)

